import json

# Theory: Only connect value-1 cells with EACH OTHER (ignore value-6 entirely for connection purposes)
# Value-6 cells are just markers that don't participate in drawing

positions_1_only = [
    (2, 2),       # VALUE 1
    (4, 14),      # VALUE 1  
    (10, 10),     # VALUE 1
    (18, 9),      # VALUE 1
]

def diag_key(r, c):
    return r - c

groups_value1 = {}
for r, c in positions_1_only:
    key = diag_key(r, c)
    if key not in groups_value1:
        groups_value1[key] = []
    groups_value1[key].append((r, c))

for key in groups_value1:
    groups_value1[key].sort()

print("Value-1 cells grouped by main diagonal:")
for key in sorted(groups_value1.keys()):
    print(f"  Main diag {key}: {groups_value1[key]}")

# Also check anti-diagonals
anti_diag_key = lambda r,c: r+c
anti_groups_value1 = {}
for r, c in positions_1_only:
    key = anti_diag_key(r, c)
    if key not in anti_groups_value1:
        anti_groups_value1[key] = []
    anti_groups_value1[key].append((r,c))

for key in anti_groups_value1:
    anti_groups_value1[key].sort()

print("\nValue-1 cells grouped by anti-diagonal:")
for key in sorted(anti_groups_value1.keys()):
    print(f"  Anti diag {key}: {anti_groups_value1[key]}")

# Now generate output: start with all special cells marked, then add diagonal connections between value-1 pairs
grid = [[4 for c in range(16)] for r in range(19)]

# All special cells (both value 1 AND value 6) appear in output
all_positions = [
    (2, 2), (4, 4), (4, 14), (6, 6), (7, 14), (10, 10), (15, 2), (18, 9),
]
for r, c in all_positions:
    grid[r][c] = 1

# Connect value-1 pairs on shared main diagonals
for key, positions in groups_value1.items():
    if len(positions) <= 1:
        continue
    positions.sort()
    for i in range(len(positions) - 1):
        p1, p2 = positions[i], positions[i+1]
        r1, c1 = p1
        r2, c2 = p2

        step_r = 1 if r2 > r1 else (-1 if r2 < r1 else 0)
        step_c = 1 if c2 > c1 else (-1 if c2 < c1 else 0)

        curr_r, curr_c = r1, c1
        while True:
            grid[curr_r][curr_c] = 1
            if (curr_r, curr_c) == (r2, c2):
                break
            curr_r += step_r
            curr_c += step_c

output = [row[:] for row in grid]
print("\nOutput:")
for row_idx, row in enumerate(output):
    print(f"Row {row_idx}: {row}")

