# This means diagonals might get broken by intervening special cells

positions_1_value1 = [(2, 2), (4, 14), (10, 10), (18, 9)]
all_special = [
    (2, 2), (4, 4), (4, 14), (6, 6), (7, 14), (10, 10), (15, 2), (18, 9)
]

def diag_key(r, c):
    return r - c

groups = {}
for r, c in positions_1_value1:
    key = diag_key(r, c)
    if key not in groups:
        groups[key] = []
    groups[key].append((r, c))

for key in groups:
