grid = [[4 for c in range(16)] for r in range(19)]

# Start with all special cells as 1
for r, c in all_special:
    grid[r][c] = 1

# For each diagonal group of value-1 cells, connect only adjacent pairs where nothing special blocks
for key, positions in groups.items():
    if len(positions) <= 1:
        continue

    for i in range(len(positions) - 1):
        p1, p2 = positions[i], positions[i+1]
        r1, c1 = p1
        r2, c2 = p2

        # Check if any special cell lies strictly between these two points
        step_r = 1 if r2 > r1 else (-1 if r2 < r1 else 0)
        step_c = 1 if c2 > c1 else (-1 if c2 < c1 else 0)

        has_blocking = False
        curr_r, curr_c = r1 + step_r, c1 + step_c
        while (curr_r, curr_c) != (r2, c2):
            if (curr_r, curr_c) in all_special:
                has_blocking = True
                break
            curr_r += step_r
            curr_c += step_c

        # Only draw connection if nothing special blocks
        if not has_blocking:
            curr_r, curr_c = r1, c1
            while True:
                grid[curr_r][curr_c] = 1
                if (curr_r, curr_c) == (r2, c2):
                    break
                curr_r += step_r
                curr_c += step_c

output = [row[:] for row in grid]
