import json

# One more theory: Value-6 cells act as RELAY points that extend diagonals in BOTH directions!
# From each value-6, draw diagonals OUTWARD until hitting boundary OR another special cell.
# Also connect min/max value-1 on shared diagonals.

value_1_cells = [(2, 2), (4, 14), (10, 10), (18, 9)]
value_6_cells = [(4, 4), (6, 6), (7, 14), (15, 2)]

grid = [[4 for c in range(16)] for r in range(19)]

# Add original values
for r, c in value_1_cells:
    grid[r][c] = 1
for r, c in value_6_cells:
    grid[r][c] = 6

def diag_key(r, c):
    return r - c

# First: Connect min/max value-1 per diagonal group
diag_groups = {}
for r, c in set(value_1_cells + value_6_cells):
    k = diag_key(r, c)
    if k not in diag_groups:
        diag_groups[k] = []
    diag_groups[k].append((r, c))

for k, positions in sorted(diag_groups.items()):
    v1_pos = [p for p in positions if p in value_1_cells]
    if len(v1_pos) >= 2:
        v1_pos.sort()
        start, end = v1_pos[0], v1_pos[-1]

        dr = 1 if end[0] > start[0] else -1
        dc = 1 if end[1] > start[1] else -1

        curr_r, curr_c = start[0], start[1]
        while True:
            grid[curr_r][curr_c] = 1
            if (curr_r, curr_c) == (end[0], end[1]):
                break
            curr_r += dr
            curr_c += dc

# Second: From each value-6, radiate OUTWARD diagonally (all 4 directions) until boundary or special cell
for r_start, c_start in value_6_cells:
    for dr, dc in [(1,1), (-1,1), (1,-1), (-1,-1)]:
        curr_r, curr_c = r_start + dr, c_start + dc

        while 0 <= curr_r < 19 and 0 <= curr_c < 16:
            # Stop if hitting any other special cell
            if (curr_r, curr_c) in value_1_cells or (curr_r, curr_c) in value_6_cells:
                break

            grid[curr_r][curr_c] = 1
            curr_r += dr
            curr_c += dc

output = [row[:] for row in grid]
print("Output (relay from value-6):")
for row_idx, row in enumerate(output):
    print(f"Row {row_idx}: {row}")

