def anti_diag_key(r, c):
    return r + c

all_specs = list(value_1_cells) + list(value_6_cells)
spec_types = {}
for p in value_1_cells:
    spec_types[p] = 'v1'
for p in value_6_cells:
    spec_types[p] = 'v6'

alignment_groups = {
    'row': defaultdict(list),
    'col': defaultdict(list),
    'main_diag': defaultdict(list),
    'anti_diag': defaultdict(list)
}

for pos in all_specs:
    alignment_groups['row'][pos[0]].append(pos)
    alignment_groups['col'][pos[1]].append(pos)
    alignment_groups['main_diag'][diag_key(*pos)].append(pos)
    alignment_groups['anti_diag'][anti_diag_key(*pos)].append(pos)

def has_intermediate_specials(p1, p2, group_dict):
    r1, c1 = p1
    r2, c2 = p2

    intermediates = []
    if r1 == r2:
        for cc in range(min(c1, c2)+1, max(c1, c2)):
            intermediates.append((r1, cc))
    elif c1 == c2:
        for rr in range(min(r1, r2)+1, max(r1, r2)):
            intermediates.append((rr, c1))
    elif diag_key(r1, c1) == diag_key(r2, c2):
        steps = abs(r2 - r1)
        dr = 1 if r2 > r1 else -1
        dc = 1 if c2 > c1 else -1
        for s in range(1, steps):
            intermediates.append((r1 + dr*s, c1 + dc*s))
    elif anti_diag_key(r1, c1) == anti_diag_key(r2, c2):
        steps = abs(r2 - r1)
        dr = 1 if r2 > r1 else -1
        dc = 1 if c2 > c1 else -1
        for s in range(1, steps):
            intermediates.append((r1 + dr*s, c1 - dc*s))

    for ir, ic in intermediates:
        if (ir, ic) in spec_types:
            return True
    return False

def fill_alignment(p1, p2, type_):
    r1, c1 = p1
    r2, c2 = p2

    grid = [[4] * 16 for _ in range(19)]
    for r, c in value_1_cells:
        grid[r][c] = 1
    for r, c in value_6_cells:
        grid[r][c] = 6

    if r1 == r2:  # Horizontal
        start, end = min(c1, c2), max(c1, c2)
        for cc in range(start, end+1):
            if grid[r1][cc] == 4:
                grid[r1][cc] = 1
    elif c1 == c2:  # Vertical
        start, end = min(r1, r2), max(r1, r2)
        for rr in range(start, end+1):
            if grid[rr][c1] == 4:
                grid[rr][c1] = 1
    elif diag_key(r1, c1) == diag_key(r2, c2):  # Main diagonal
        steps = abs(r2 - r1)
        dr = 1 if r2 > r1 else -1
        dc = 1 if c2 > c1 else -1
        for s in range(steps+1):
            rr, cc = r1 + dr*s, c1 + dc*s
            if grid[rr][cc] == 4:
                grid[rr][cc] = 1
    elif anti_diag_key(r1, c1) == anti_diag_key(r2, c2):  # Anti diagonal
        steps = abs(r2 - r1)
        dr = 1 if r2 > r1 else -1
        dc = 1 if c2 > c1 else -1
        for s in range(steps+1):
            rr, cc = r1 + dr*s, c1 - dc*s
            if grid[rr][cc] == 4:
                grid[rr][cc] = 1

    return grid

# Find all aligned pairs of same-type that DON'T have intervening specials
print("\n\nSame-type aligned pairs without intermediate specials:")
aligned_pairs = []

for type_ in ['row', 'col', 'main_diag', 'anti_diag']:
    groups = alignment_groups[type_]
    for k, positions in groups.items():
        if len(positions) >= 2:
            positions_sorted = sorted(positions, key=lambda x: x[0])
            types_list = [spec_types[p] for p in positions_sorted]

            i = 0
            while i < len(positions_sorted) - 1:
                if types_list[i] == types_list[i+1]:
                    p1, p2 = positions_sorted[i], positions_sorted[i+1]
                    if not has_intermediate_specials(p1, p2, spec_types):
                        aligned_pairs.append((p1, p2, type_, None, None))
                elif types_list[i] != types_list[i+1]:
                    # Check if there's a valid sub-segment within this block
                    j = i + 1
                    while j < len(positions_sorted) and types_list[j] != types_list[i]:
                        j += 1

                    # Within [i:j], connect same-type consecutive pairs
                    for idx in range(i, j):
                        p_curr = positions_sorted[idx]
                        p_next = positions_sorted[idx+1]
                        if types_list[idx] == types_list[idx+1]:
                            if not has_intermediate_specials(p_curr, p_next, spec_types):
                                aligned_pairs.append((p_curr, p_next, type_, None, None))
                    i = j
                else:
                    i += 1

for p1, p2, type_, _, _ in aligned_pairs:
    print(f"  {p1}-{p2} ({type_})")

if aligned_pairs:
    # Fill all aligned pairs
    final_grid = [[4] * 16 for _ in range(19)]
    for r, c in value_1_cells:
        final_grid[r][c] = 1
    for r, c in value_6_cells:
        final_grid[r][c] = 6

    for p1, p2, type_, _, _ in aligned_pairs:
        r1, c1 = p1
        r2, c2 = p2

        if r1 == r2:
            for cc in range(min(c1, c2), max(c1, c2)+1):
                if final_grid[r1][cc] == 4:
                    final_grid[r1][cc] = 1
        elif c1 == c2:
            for rr in range(min(r1, r2), max(r1, r2)+1):
                if final_grid[rr][c1] == 4:
                    final_grid[rr][c1] = 1
        elif diag_key(r1, c1) == diag_key(r2, c2):
            steps = abs(r2 - r1)
            dr = 1 if r2 > r1 else -1
            dc = 1 if c2 > c1 else -1
            for s in range(steps+1):
                rr, cc = r1 + dr*s, c1 + dc*s
                if final_grid[rr][cc] == 4:
                    final_grid[rr][cc] = 1
        elif anti_diag_key(r1, c1) == anti_diag_key(r2, c2):
            steps = abs(r2 - r1)
            dr = 1 if r2 > r1 else -1
            dc = 1 if c2 > c1 else -1
            for s in range(steps+1):
                rr, cc = r1 + dr*s, c1 - dc*s
                if final_grid[rr][cc] == 4:
                    final_grid[rr][cc] = 1

    output = [row[:] for row in final_grid]
    print(json.dumps({"action": "submit", "output": output}))
else:
    print("No aligned pairs found - unchanged grid")
    output = [[4]*16 for _ in range(19)]
    for r, c in value_1_cells:
        output[r][c] = 1
    for r, c in value_6_cells:
        output[r][c] = 6
    print(json.dumps({"action": "submit", "output": output}))

# THEORY: Value-1 emits RAYS in 4 diagonal directions until hitting boundary or another special cell

value_1_cells = [(2, 2), (4, 14), (10, 10), (17, 9)]
value_6_cells = [(4, 4), (6, 6), (7, 14), (15, 2)]

def diag_key(r, c):
    return r - c

grid = [[4] * 16 for _ in range(19)]
for r, c in value_1_cells:
    grid[r][c] = 1
for r, c in value_6_cells:
    grid[r][c] = 6

print("Value-1 positions:", value_1_cells)
print("Value-6 positions:", value_6_cells)

def fill_ray(p1, p2, preserve_specials=True):
    sr, sc = p1
    er, ec = p2

    rr, cc = sr, sc
    while True:
        if grid[rr][cc] == 4:
            grid[rr][cc] = 1
        elif preserve_specials:
            pass  # Keep existing specials
        if (rr, cc) == (er, ec):
            break
        rr += dr
        cc += dc

directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

for vr, vc in directions:
    for vr_start, vc_start in value_1_cells:
        rr, cc = vr_start + vr, vc_start + vc
        while 0 <= rr < 19 and 0 <= cc < 16:
            if grid[rr][cc] != 4:
                break  # Hit something non-background
            fill_ray((vr_start, vc_start), (rr, cc))
            break
            rr += vr
            cc += vc
        else:
            rr += vr
            cc += vc
            while 0 <= rr < 19 and 0 <= cc < 16:
                if grid[rr][cc] != 4:
                    break
                fill_ray((vr_start, vc_start), (rr, cc))
                break
                rr += vr
                cc += vc

output = [row[:] for row in grid]
print(json.dumps({"action": "submit", "output": output}))

# THEORY: Connect CONSECUTIVE pairs along the main diagonal, filling gaps between them
# Preserve BOTH V1 and V6 values, only fill background cells between consecutive specials

value_1_cells = [(2, 2), (4, 14), (10, 10), (17, 9)]
value_6_cells = [(4, 4), (6, 6), (7, 14), (15, 2)]

def diag_key(r, c):
    return r - c

grid = [[4] * 16 for _ in range(19)]
for r, c in value_1_cells:
    grid[r][c] = 1
for r, c in value_6_cells:
    grid[r][c] = 6

from collections import defaultdict

# Group ALL specials by diagonal
groups = defaultdict(list)
for pos in value_1_cells + value_6_cells:
    groups[diag_key(*pos)].append(pos)

def fill_gap(p1, p2, preserve=True):
    sr, sc = p1
    er, ec = p2
    dr, dc = 1 if er > sr else -1, 1 if ec > sc else -1

    rr, cc = sr, sc
    while True:
        if (rr, cc) != p1 and (rr, cc) != p2:
            if grid[rr][cc] == 4:
                grid[rr][cc] = 1

        if (rr, cc) == (er, ec):
            break
        rr += dr
        cc += dc

for k, positions in sorted(groups.items()):
    if len(positions) >= 2:
        # Sort by row position
        positions_sorted = sorted(positions, key=lambda x: x[0])

        for i in range(len(positions_sorted)-1):
            p1, p2 = positions_sorted[i], positions_sorted[i+1]
            fill_gap(p1, p2)
            print(f"Filled {p1} -> {p2}")

output = [row[:] for row in grid]
print(json.dumps({"action": "submit", "output": output}))

# THEORY: Connect ONLY different-type pairs (V1-V6 or V6-V1) on diagonal, skip same-type (V6-V6)

value_1_cells = [(2, 2), (4, 14), (10, 10), (17, 9)]
value_6_cells = [(4, 4), (6, 6), (7, 14), (15, 2)]

grid = [[4] * 16 for _ in range(19)]
for r, c in value_1_cells:
    grid[r][c] = 1
for r, c in value_6_cells:
    grid[r][c] = 6

def diag_key(r, c):
    return r - c

from collections import defaultdict

all_specs = list(value_1_cells) + list(value_6_cells)
groups = defaultdict(list)
for pos in all_specs:
    groups[diag_key(*pos)].append(pos)

def fill_between(p1, p2):
    sr, sc = p1
    er, ec = p2
    dr, dc = 1 if er > sr else -1, 1 if ec > sc else -1

    rr, cc = sr, sc
    while True:
        if (rr, cc) != p1 and (rr, cc) != p2 and grid[rr][cc] == 4:
            grid[rr][cc] = 1
        if (rr, cc) == (er, ec):
            break
        rr += dr
        cc += dc

for k, positions in sorted(groups.items()):
    if len(positions) >= 2:
        positions_sorted = sorted(positions, key=lambda x: x[0])

        # Filter: connect only DIFFERENT type pairs
        filtered = []
        for i in range(len(positions_sorted)-1):
            p1, p2 = positions_sorted[i], positions_sorted[i+1]
            if (p1 in value_1_cells) != (p2 in value_1_cells):
                filtered.append((p1, p2))

        print(f"k={k}: {positions} -> connecting different-types: {filtered}")

        for p1, p2 in filtered:
            fill_between(p1, p2)

output = [row[:] for row in grid]
